import { existsSync, readFileSync } from "node:fs";
import type { DeputiesDataset, MandatesDataset } from "#lib/deputies.ts";

// Generated by `pnpm data:deputies` (the deploy runs it) and not versioned:
// without it the site still builds, with an empty list.
const PATH = "src/lib/data/deputies.json";

export const deputies: DeputiesDataset | null = existsSync(PATH)
  ? JSON.parse(readFileSync(PATH, "utf8"))
  : null;

// Every deputy since 1826, also generated by `pnpm data:deputies`.
const MANDATES = "src/lib/data/deputies-mandates.json";

export const mandates: MandatesDataset | null = existsSync(MANDATES)
  ? JSON.parse(readFileSync(MANDATES, "utf8"))
  : null;
